const xpages = [
  { slug: 'ephys', title: 'Patch clamp to model', level: 'Electrophysiology', blurb: 'Record current steps from a (synthetic) CA1 cell, fit a model by hand or automatically, then test it on data it never saw.' },
  { slug: 'place-cells', title: 'Place cells & behavior', level: 'Behavior + recording', blurb: 'A rat explores while its place cells fire. Build rate maps, watch phase precession, decode position from spikes.' },
  { slug: 'ca1-circuit', title: 'The CA1 circuit', level: 'Anatomy + pathways', blurb: 'Layered CA1 with realistic pyramidal neurons and interneurons. Stimulate CA3 or entorhinal inputs and follow the signal.' },
];
