      const ref = meds[3] * Math.sqrt(20); x.strokeStyle = '#8a7058'; x.setLineDash([4, 3]); x.beginPath(); ns.forEach((n, k) => { const v = Math.min(mxE, ref / Math.sqrt(n)); k ? x.lineTo(X(n), Y(v)) : x.moveTo(X(n), Y(v)); }); x.stroke(); x.setLineDash([]);
