const AAC_DATA = {"g_nS":[0,1,2,3,4,6,8,10,14,20],"dt_ms":[-10,-8,-6,-4,-3,-2,-1,0,0.5,1,1.5,2,3],"egaba":{"-75.0":{"rheobase_nA":0.7236,"amp_nA":0.7598,"baseline_latency_ms":4.786,"latency":[[4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786],[5.545,5.786,6.118,6.587,6.866,7.113,7.075,6.398,5.892,5.459,5.046,4.921,4.813],[null,null,null,null,null,null,null,null,null,null,5.582,5.075,4.826],[null,null,null,null,null,null,null,null,null,null,null,5.26,4.849],[null,null,null,null,null,null,null,null,null,null,null,5.519,4.866],[null,null,null,null,null,null,null,null,null,null,null,null,4.904],[null,null,null,null,null,null,null,null,null,null,null,null,4.941],[null,null,null,null,null,null,null,null,null,null,null,null,4.973],[null,null,null,null,null,null,null,null,null,null,null,null,5.048],[null,null,null,null,null,null,null,null,null,null,null,null,5.167]]},"-55.0":{"rheobase_nA":0.7236,"amp_nA":0.7598,"baseline_latency_ms":4.786,"latency":[[4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786,4.786],[4.555,4.523,4.518,4.554,4.586,4.646,4.729,4.825,4.843,4.825,4.813,4.802,4.786],[4.37,4.322,4.312,4.366,4.416,4.516,4.66,4.848,4.9,4.88,4.845,4.806,4.786],[4.206,4.151,4.135,4.204,4.292,4.408,4.627,4.889,4.943,4.946,4.869,4.806,4.8],[4.065,4.01,3.992,4.068,4.167,4.316,4.568,4.919,4.996,4.974,4.891,4.816,4.801],[3.83,3.742,3.735,3.849,3.965,4.181,4.505,4.972,5.095,5.084,4.94,4.825,4.802],[3.604,3.509,3.51,3.65,3.816,4.047,4.452,5.022,5.198,5.162,4.996,4.839,4.801],[3.411,3.312,3.312,3.494,3.685,3.962,4.41,5.092,5.289,5.251,5.024,4.837,4.806],[3.105,3.014,3.041,3.24,3.482,3.816,4.335,5.178,5.467,5.431,5.147,4.864,4.827],[2.811,2.752,2.786,3.021,3.284,3.689,4.295,5.323,5.688,5.653,5.263,4.891,4.842]]}}};
function renderAxoAxonic() {
  document.title = 'Axo-axonic synapses at the AIS · Real biology';
  const D = AAC_DATA, H = D.egaba['-75.0'], Dp = D.egaba['-55.0'];
  $('lesson').innerHTML = bioHead('Axo-axonic synapses at the AIS', 'REAL BIOLOGY · NEURON · REAL CA1 CELL + CHANDELIER INPUT · LINKS TO THE FLY GIANT FIBER', 'Chandelier cells put their synapses on the axon initial segment (AIS), right where spikes start. Do they veto spikes or help trigger them? Here a real CA1 pyramidal cell is simulated in NEURON with GABA-A synapses on its AIS, sweeping synaptic strength, timing and the chloride gradient.')
    + `<nav class="page-jumps"><a href="#aac-map">Veto maps</a><a href="#aac-slice">Timing curve</a><a href="#aac-why">Why it matters</a><a href="#aac-uth">Model details</a><a href="/biology/cell-atlas/">Real chandelier cells →</a><a href="/biology/giant-fiber/">Fly axo-axonic inputs →</a></nav>
    <section class="lesson-section lab" id="aac-map"><p class="eyebrow">01 · Predict → change → observe</p><h2>When does an AIS synapse stop the spike?</h2>
      <p>The soma gets a 2 ms current pulse 5% above threshold (${H.amp_nA.toFixed(2)} nA), which fires the cell after ${H.baseline_latency_ms.toFixed(2)} ms. One GABA-A synapse on the AIS is activated at a time Δt relative to the pulse. Predict: with the usual hyperpolarising chloride gradient, how late can the synapse arrive and still block the spike? What changes if chloride makes GABA depolarising at the AIS?</p>
      <div class="gf-two"><div><h3>E<sub>GABA</sub> = −75 mV (hyperpolarising)</h3><canvas id="aacH" class="uth-plot" style="height:300px" aria-label="Spike latency map, hyperpolarising GABA"></canvas></div>
      <div><h3>E<sub>GABA</sub> = −55 mV (depolarising at rest)</h3><canvas id="aacD" class="uth-plot" style="height:300px" aria-label="Spike latency map, depolarising GABA"></canvas></div></div>
      <div class="uth-key"><span><i style="background:#3a2a1c"></i>spike blocked</span><span><i style="background:hsl(250 70% 50%)"></i>earlier spike</span><span><i style="background:hsl(125 60% 75%)"></i>no change</span><span><i style="background:hsl(0 70% 50%)"></i>later spike</span></div>
      <div id="aacTip" class="ml-fp">Hover over a cell of either map to see the exact latency.</div></section>
    <section class="lesson-section lab" id="aac-slice"><p class="eyebrow">02 · Slice through the map</p><h2>Timing curve at one synaptic strength</h2>
      <div class="nv-wrap"><canvas id="aacS" class="nv-canvas" style="height:300px"></canvas><div class="lab-controls">${ctl2('aacG', 'GABA-A peak conductance', 1, D.g_nS.length - 1, 1, 3, 'nS (index into the simulated values)')}<div id="aacSOut" class="ml-fp"></div></div></div></section>
    <section class="lesson-section" id="aac-why"><p class="eyebrow">03 · Why it matters</p><h2>One synapse, two opposite effects</h2>
      <ul class="skill-tips"><li><b>Hyperpolarising chloride:</b> a 2 nS synapse arriving up to about 1 ms after the pulse onset vetoes the spike. Once the AIS has fired (from about 1.5 ms), the same synapse only delays the spike, by up to about 0.8 ms, and by 3 ms it has almost no effect. Chandelier control is a <b>narrow timing window</b>, not a constant brake.</li>
      <li><b>Depolarising chloride:</b> the synapse never blocks. Arriving before the pulse, it <b>advances</b> the spike (by up to about 2 ms at 20 nS). Arriving with or just after the pulse, its shunt slightly <b>delays</b> it. Whether chandelier cells are "excitatory" depends on the chloride gradient <i>and</i> on timing.</li>
      <li>The debate is real. Cortical slice work reported excitatory axo-axonic effects (Szabadics et al. 2006), hippocampal measurements found hyperpolarising GABA along the whole axis including the AIS (Glickfeld et al. 2009), and in vivo hippocampal axo-axonic cells inhibit pyramidal cells during behaviour (Dudok et al. 2021).</li>
      <li><b>Bridge to the fly:</b> in the MANC connectome the AN08B098 (Axc) cells contacting the giant-fibre axon are predicted <i>cholinergic</i>, and activating them raised GF firing (Ceballos et al. 2026). Same anatomical motif, opposite sign: axo-axonic placement is a general way to gate spike output.</li>
      <li><b>Next step for your axoaxonic-learning-model:</b> this is that model's "deferred" item, a biological CA1 reconstruction, already running. Add the timing × conductance sweep with your E<sub>GABA</sub> values, or plasticity of AIS position (Pan-Vazquez et al. 2020).</li></ul></section>
    <section class="lesson-section" id="aac-uth"><p class="eyebrow">04 · Model details</p><h2>Under the hood</h2>
      <details class="uth" open><summary><span>Under the hood</span> cell, AIS, synapse, protocol</summary><div class="uth-grid">
        <section><h4>Cell</h4><p>CA1 pyramidal mpg141209_A (Migliore et al. 2018 reconstruction, rat) with the Migliore et al. (2005) channel set (same as the active-dendrites page). The traced axon is replaced by a standard <b>hillock</b> (10 µm, 2 µm diameter), <b>AIS</b> (30 µm, 1.2 µm, Na⁺ 5× somatic) and <b>axon</b> (400 µm, 1 µm), so AIS geometry is controlled. Steady-state start at −65 mV.</p></section>
        <section><h4>Synapse</h4><p>One NEURON <code>Exp2Syn</code> at the AIS midpoint: \\(g(t)=\\bar g\\,\\frac{e^{-t/\\tau_2}-e^{-t/\\tau_1}}{\\max}\\), τ<sub>1</sub> = 0.5 ms, τ<sub>2</sub> = 8 ms, \\(I = g(t)(V-E_{GABA})\\). This lumps a chandelier cartridge (several boutons on one AIS) into a single conductance: ${D.g_nS.join(', ')} nS.</p></section>
        <section><h4>Protocol</h4><p>Rheobase for a 2 ms somatic pulse was found by bisection (${H.rheobase_nA} nA); the test pulse is 1.05× that. Δt = synapse onset − pulse onset: ${D.dt_ms.join(', ')} ms. Spike = somatic V crossing 0 mV; latency is measured from pulse onset. CVODE, 50 ms per trial, ${D.g_nS.length * D.dt_ms.length * 2} trials.</p></section>
        <section><h4>Limits</h4><p>A single cell and a lumped synapse. There is no K<sub>v</sub>1 or Na<sub>v</sub>1.6/1.2 split at the AIS, and no realistic AIS chloride dynamics (E<sub>GABA</sub> is fixed per run). Spike threshold is measured at one stimulus strength. Use this to form hypotheses, then test them with AIS-specific channel models.</p></section></div></details></section>
    <section class="lesson-section" id="code"><p class="eyebrow">05 · Do it in Python</p><h2>Reproduce one row of the map</h2><div class="code-toolbar"><span>Python 3 · neuron</span></div><pre><code># Uses the channel files from ModelDB 55035 (git clone https://github.com/ModelDBRepository/55035; nrnivmodl .)
from neuron import h
h.load_file("stdrun.hoc")
soma = h.Section(name="soma"); soma.L = soma.diam = 20
hill = h.Section(name="hill"); hill.L, hill.diam = 10, 2; hill.connect(soma(0.5))
ais = h.Section(name="ais"); ais.L, ais.diam = 30, 1.2; ais.connect(hill(1))
for s in (soma, hill, ais):
    s.insert("pas"); s.g_pas, s.e_pas, s.Ra, s.cm = 1 / 28000, -65, 150, 1
    s.insert("kdr"); s.gkdrbar_kdr = 0.01; s.ek = -90; s.nseg = 5
soma.insert("na3"); soma.gbar_na3 = 0.025; soma.ena = 55
for s in (hill, ais): s.insert("nax"); s.ena = 55
hill.gbar_nax, ais.gbar_nax = 0.05, 0.125
syn = h.Exp2Syn(ais(0.5)); syn.tau1, syn.tau2, syn.e = 0.5, 8, -75      # try e = -55
ns = h.NetStim(); ns.number = 1; nc = h.NetCon(ns, syn); nc.weight[0] = 0.0002  # 0.2 nS: this toy cell is tiny (high input resistance), so it needs ~10× less than the full cell
st = h.IClamp(soma(0.5)); st.delay, st.dur = 20, 2
def init():          # make −65 mV a true resting state (same trick as the original model code)
    h.finitialize(-65); h.fcurrent()
    for s in (soma, hill, ais):
        for seg in s: seg.e_pas = seg.v + (seg.ina + seg.ik) / seg.g_pas
    h.finitialize(-65)
def spikes(amp, dt):
    st.amp = amp; ns.start = 20 + dt
    v = h.Vector().record(soma(0.5)._ref_v); t = h.Vector().record(h._ref_t); init(); h.continuerun(50)
    up = [t[i] - 20 for i in range(1, len(v)) if v[i - 1] < 0 <= v[i]]
    return round(up[0], 2) if up else None          # spike latency (ms) or None = blocked
lo, hi = 0.001, 3.0                     # rheobase by bisection (no synapse: start it after the run)
for _ in range(14):
    mid = (lo + hi) / 2; (hi, lo) = (mid, lo) if spikes(mid, 1e3) is not None else (hi, mid)
amp = 1.5 * hi; print('rheobase', round(hi, 3), 'nA; latency without synapse', spikes(amp, 1e3), 'ms')
print({dt: spikes(amp, dt) for dt in (-6, -3, -1, 0, 1, 2, 4, 6, 8)})   # latency, or None if the AIS synapse blocked the spike
# Expected (checked): no synapse 12.6 ms; with 0.2 nS the spike is delayed most when the synapse comes first (≈19 ms at Δt = −6).
# Raise the weight to see blocks, and set syn.e = -55 to see the depolarising case advance the spike.</code></pre>
      <p class="muted">This is a minimal three-compartment version. The map above uses the full reconstruction.</p></section>
    <section class="lesson-section reading"><p class="eyebrow">Sources</p><ol class="gf-refs">
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Excitatory+effect+of+GABAergic+axo-axonic+cells+in+cortical+microcircuits" target="_blank" rel="noopener">Szabadics J et al. (2006) Excitatory effect of GABAergic axo-axonic cells in cortical microcircuits. Science 311:233–235 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Interneurons+hyperpolarize+pyramidal+cells+along+their+entire+somatodendritic+axis" target="_blank" rel="noopener">Glickfeld LL, Roberts JD, Somogyi P, Scanziani M (2009) Interneurons hyperpolarize pyramidal cells along their entire somatodendritic axis. Nat Neurosci 12:21–23 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Recruitment+and+inhibitory+action+of+hippocampal+axo-axonic+cells+during+behavior" target="_blank" rel="noopener">Dudok B et al. (2021) Recruitment and inhibitory action of hippocampal axo-axonic cells during behavior. Neuron 109:3838–3850 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Activity-dependent+plasticity+of+axo-axonic+synapses+at+the+axon+initial+segment" target="_blank" rel="noopener">Pan-Vazquez A et al. (2020) Activity-dependent plasticity of axo-axonic synapses at the axon initial segment. Neuron 106:265–276 ↗</a></li>
      <li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4471148/" target="_blank" rel="noopener">Viney TJ et al. (2013) Network state-dependent inhibition of identified hippocampal CA3 axons by axo-axonic cells. Nat Neurosci 16:1802–1811 ↗</a></li>
      <li><a href="https://doi.org/10.1016/j.isci.2026.115624" target="_blank" rel="noopener">Ceballos CC et al. (2026) The Drosophila connectome reveals axo-axonic synapses on descending neurons. iScience 29(5):115624 ↗</a></li></ol></section>`;
  typeset(); aacInit(D);
}
function aacInit(D) {
  const base = D.egaba['-75.0'].baseline_latency_ms, cells = {};
  const col = v => v == null ? '#3a2a1c' : (() => { const d = v - base; const t = Math.max(-1, Math.min(1, d / 1.5)); return t < 0 ? `hsl(${125 + 125 * -t} 65% ${75 - 25 * -t}%)` : `hsl(${125 - 125 * t} 65% ${75 - 25 * t}%)`; })();
  const heat = (id, key) => {
    const R = D.egaba[key], [x, W, H] = gfCanvas(id), L = 52, B = H - 34, T = 8, Rr = W - 8, nx = D.dt_ms.length, ny = D.g_nS.length, cw = (Rr - L) / nx, ch = (B - T) / ny;
    R.latency.forEach((row, j) => row.forEach((v, i) => { x.fillStyle = col(v); x.fillRect(L + i * cw, B - (j + 1) * ch, cw - 1, ch - 1); }));
    x.fillStyle = '#6f4c27'; x.font = '10px system-ui';
    D.dt_ms.forEach((d, i) => { if (i % 2 === 0 || d === 0) x.fillText(d, L + i * cw + cw / 2 - 6, B + 12); }); x.fillText('Δt synapse − pulse (ms)', L, H - 6);
    D.g_nS.forEach((g, j) => x.fillText(g + ' nS', 4, B - j * ch - ch / 2 + 4));
    cells[id] = { L, B, cw, ch, R };
  };
  heat('aacH', '-75.0'); heat('aacD', '-55.0');
  ['aacH', 'aacD'].forEach(id => $(id).onmousemove = e => {
    const c = cells[id], r = $(id).getBoundingClientRect(), i = Math.floor((e.clientX - r.left - c.L) / c.cw), j = Math.floor((c.B - (e.clientY - r.top)) / c.ch);
    if (i < 0 || j < 0 || i >= D.dt_ms.length || j >= D.g_nS.length) return; const v = c.R.latency[j][i];
    $('aacTip').innerHTML = `${id === 'aacH' ? 'Hyperpolarising' : 'Depolarising'} GABA, ${D.g_nS[j]} nS at Δt = ${D.dt_ms[i]} ms: ${v == null ? '<b>spike blocked</b>' : `spike at <b>${v.toFixed(2)} ms</b> (${(v - base >= 0 ? '+' : '') + (v - base).toFixed(2)} ms vs no synapse)`}`;
  });
  const slice = () => {
    const j = +$('aacG').value, g = D.g_nS[j]; $('aacG-o').textContent = g + ' nS';
    const [x, W, H] = gfCanvas('aacS'), L = 46, B = H - 32, T = 12, Rr = W - 12, d0 = D.dt_ms[0], d1 = D.dt_ms[D.dt_ms.length - 1], X = d => L + (Rr - L) * (d - d0) / (d1 - d0), y0 = 2.5, y1 = 6, Y = v => B - (B - T) * (v - y0) / (y1 - y0);
    x.strokeStyle = '#e6d8c8'; x.font = '11px system-ui'; for (let v = 3; v <= 6; v++) { x.beginPath(); x.moveTo(L, Y(v)); x.lineTo(Rr, Y(v)); x.stroke(); x.fillStyle = '#6f4c27'; x.fillText(v + ' ms', 4, Y(v) + 4); }
    D.dt_ms.forEach(d => { if (Number.isInteger(d)) x.fillText(d, X(d) - 4, H - 16); }); x.fillText('Δt (ms)', L, H - 2);
    x.setLineDash([4, 4]); x.strokeStyle = '#999'; x.beginPath(); x.moveTo(L, Y(base)); x.lineTo(Rr, Y(base)); x.stroke(); x.setLineDash([]);
    [['-75.0', '#3d6a8c'], ['-55.0', '#a62962']].forEach(([k, c]) => { const row = D.egaba[k].latency[j]; x.strokeStyle = c; x.fillStyle = c; x.lineWidth = 2; x.beginPath(); let st = false;
      row.forEach((v, i) => { const xx = X(D.dt_ms[i]); if (v == null) { x.stroke(); st = false; x.font = 'bold 13px system-ui'; x.fillText('×', xx - 4, B - 4); x.font = '11px system-ui'; x.beginPath(); return; } const yy = Y(v); st ? x.lineTo(xx, yy) : x.moveTo(xx, yy); st = true; x.fillRect(xx - 2, yy - 2, 4, 4); }); x.stroke(); });
    x.lineWidth = 1;
    const blocked = D.egaba['-75.0'].latency[j].map((v, i) => v == null ? D.dt_ms[i] : null).filter(v => v != null);
    $('aacSOut').innerHTML = `<p><span style="color:#3d6a8c">■</span> hyperpolarising, <span style="color:#a62962">■</span> depolarising; dashed = no synapse (${base.toFixed(2)} ms); × = blocked.</p><p>At ${g} nS the hyperpolarising synapse blocks the spike for Δt ${blocked.length ? `from ${Math.min(...blocked)} to ${Math.max(...blocked)} ms` : 'never'}.</p>`;
  };
  $('aacG').oninput = slice; slice();
}
window.renderAxoAxonic = renderAxoAxonic;
