    psi: { soma: circ(5), sections: [[3, -1, line(0, 0, -40, 0, 4), rad(4, 1.5)], [2, -1, line(0, 0, 80, 0, 8), rad(8, 1.5)]] },
    dlmn: { soma: circ(9), sections: [[3, -1, line(0, 0, -50, 0, 5), rad(5, 2.5)], [2, -1, line(0, 0, 0, -ta, Math.ceil(ta / 10)), rad(Math.ceil(ta / 10), 3)]] }
