  ah: V => 0.07 * Math.exp(-(V + 65) / 20),
  bh: V => 1 / (1 + Math.exp(-(V + 35) / 10)),
  an: V => { const u = V + 55; return Math.abs(u) < 1e-6 ? 0.1 : 0.01 * u / (1 - Math.exp(-u / 10)); },
