    for (let mm = 0; mm < 4; mm++) for (let hh = 0; hh < 2; hh++) popNa[mm * 2 + hh] = Math.round(nNa * C(3, mm) * P.m ** mm * (1 - P.m) ** (3 - mm) * (hh ? P.h : 1 - P.h));
