  bindS('apTTX', v => o.ttx = v / 100); bindS('apTEA', v => o.tea = v / 100); ['apAmp', 'apDur', 'apGap', 'apHold'].forEach(id => bindS(id, () => {}));
  $('apNoise').onchange = e => o.noise = e.target.checked; $('apArea').onchange = e => o.area = +e.target.value;
