    x.fillStyle = '#6f4c27'; x.textAlign = 'center'; [0.5, 1, 2, 5, 10, 20, 50, 100].forEach(f => x.fillText(f, ax.X(lx(f)), ax.B + 15)); x.textAlign = 'left';
